    for col in required:
        if col not in df.columns:
            raise ValueError(f"Missing required column: {col}")

    working = df.copy()

    result = (
        working.groupby("region", as_index=False)
        .agg(total_revenue=("revenue", "sum"), total_units=("units", "sum"))
